// Define a default initial capacity for the buffer for clarity
#define INITIAL_BUFFER_CAPACITY 20

void setUp(void) {
    // No specific setup needed for this test path
}

void tearDown(void) {
    // No specific cleanup needed for this test path beyond what's in the test itself
}

void unit_test_buffer_append_n_sufficient_capacity(void) {
    // Setup: Create a buffer with enough initial capacity to avoid resize
    // Initial content: "Hello" (length 5)
    // String to append: " World" (length 6)
    // Total needed length: 5 + 6 = 11
    // We need self->len > 11. Let's use INITIAL_BUFFER_CAPACITY = 20.
    buffer_t *buf = helper_create_buffer_with_size(INITIAL_BUFFER_CAPACITY);
    TEST_ASSERT_NOT_NULL(buf);

    // Initialize the buffer with some data
    const char *initial_data = "Hello";
    strcpy(buf->data, initial_data); // Copy "Hello" into the buffer
    // Ensure it's null-terminated, which strcpy does.
    // buffer_new_with_size already ensures the entire allocated region is zeroed,
    // so the null terminator is implicitly handled after strcpy.

    // Verify initial state
    TEST_ASSERT_EQUAL_STRING(initial_data, buf->data);
    TEST_ASSERT_EQUAL_INT(strlen(initial_data), buffer_length(buf));
    TEST_ASSERT_EQUAL_INT(INITIAL_BUFFER_CAPACITY, buffer_size(buf));

    // Inputs for the function under test
    const char *str_to_append = " World";
    size_t len_to_append = 6; // Append " World" (6 characters)

    // Test: Call buffer_append_n
    // This path expects self->len (20) > (strlen("Hello") + 6) (5 + 6 = 11), which is true.
    // So, no resize should occur.
    int ret = buffer_append_n(buf, str_to_append, len_to_append);

    // Assertions
    TEST_ASSERT_EQUAL_INT(0, ret); // Should return 0 for success
    TEST_ASSERT_EQUAL_STRING("Hello World", buf->data); // Verify appended content
    TEST_ASSERT_EQUAL_INT(strlen("Hello World"), buffer_length(buf)); // Verify new length
    TEST_ASSERT_EQUAL_INT(INITIAL_BUFFER_CAPACITY, buffer_size(buf)); // Capacity should remain unchanged

    // Cleanup
    buffer_free(buf);
}

int main(void) {
    UNITY_BEGIN();
    RUN_TEST(unit_test_buffer_append_n_sufficient_capacity);
    return UNITY_END();
}

